class Solution:
    def maxSelectedElements(self, nums: list[int]) -> int:
        a = sorted(nums)
        n = len(a)
        ans = 1
        for l in range(n):
            mx, mn = a[l] - l, a[l] + 1 - l
            for r in range(l, n):
                mx = max(mx, a[r] - r)
                mn = min(mn, a[r] + 1 - r)
                if mx > mn:
                    break
                ans = max(ans, r - l + 1)
        return ans

