class Solution {
public:
    int maxSelectedElements(vector<int>& nums) {
        vector<int> a = nums;
        sort(a.begin(), a.end());
        int n = a.size(), ans = 1;
        for (int l = 0; l < n; l++) {
            int mx = a[l] - l, mn = a[l] + 1 - l;
            for (int r = l; r < n; r++) {
                mx = max(mx, a[r] - r);
                mn = min(mn, a[r] + 1 - r);
                if (mx > mn) break;
                ans = max(ans, r - l + 1);
            }
        }
        return ans;
    }
};

