            if (a[i-1] == a[i] - 1 || a[i-1] == a[i] - 2) nd1 = 1 + max(d1, d2);
            if (a[i-1] == a[i]) nd2 = 1 + d1;
            d1 = nd1; d2 = nd2;
            ans = max({ans, d1, d2});
        }
        return ans;
    }
};

